SELECT CASE WHEN s.device IN ('desktop', 'tablet') THEN 'tier_1' ELSE 'other' END AS device_group, ROUND((100 * SUM(CASE WHEN we.page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout FROM web_events we FULL OUTER JOIN sessions s ON we.session_id = s.id GROUP BY CASE WHEN s.device IN ('desktop', 'tablet') THEN 'tier_1' ELSE 'other' END;
